import numpy as np
def rects(g):
    g = np.asarray(g); seen = np.zeros_like(g, bool); out=[]
    for r in range(g.shape[0]):
        for c in range(g.shape[1]):
            v = g[r,c]
            if v and not seen[r,c]:
                stack=[(r,c)]; cells=[]
                seen[r,c]=True
                while stack:
                    y,x = stack.pop()
                    if g[y,x]!=v: continue
                    cells.append((y,x))
                    for dy in(-1,0,1):
                        for dx in(-1,0,1):
                            ny,nx=y+dy,x+dx
                            if 0<=ny<g.shape[0] and 0<=nx<g.shape[1] and not seen[ny,nx] and g[ny,nx]==v:
                                seen[ny,nx]=True; stack.append((ny,nx))
                ys=[y for y,x in cells]; xs=[x for y,x in cells]
                r0,r1,c0,c1=min(ys),max(ys),min(xs),max(xs)
                if len(cells)==(r1-r0+1)*(c1-c0+1):  # solid rectangle
                    inner = g[r0+1:r1, c0+1:c1]
                    out.append(dict(col=int(v), rows=(r0,r1), cols=(c0,c1), ih=r1-r0-1, iw=c1-c0-1,
                                    nnz=int((inner==v).sum())))
    return out
