def rects2(g):
    g = np.asarray(g); out=[]
    from scipy.ndimage import label
    for v in np.unique(g):
        if v==0: continue
        lab,n = label(g==v, structure=np.ones((3,3)))
        for i in range(1,n+1):
            yy,xx = np.where(lab==i)
            r0,r1,c0,c1 = yy.min(),yy.max(),xx.min(),xx.max()
            sub_ = g[r0:r1+1, c0:c1+1]; h,w = sub_.shape
            if (sub_[0]==v).all() and (sub_[-1]==v).all() and (sub_[:,0]==v).all() and (sub_[:,-1]==v).all():
                inner = sub_[1:h-1, 1:w-1]
                out.append((int(v), r0, r1, c0, c1, h-2, w-2, int((inner==v).sum())))
    return sorted(out)
